-- Esquema general del tema (nodo_id NULL)
INSERT INTO opouj_wp_uji_esquemas (tema_id, nodo_id, contenido_html)
VALUES (9, NULL, '<h2>Tema 9 en síntesis</h2><ul><li>Fundamento: autonomía parlamentaria (<span class="uji-esq__ref">art. 72.1 CE</span>) → Estatuto del Personal de las Cortes Generales (2025).</li><li>4 clases de personal: funcionario, eventual, adscrito de la AGE, laboral.</li><li>7 Cuerpos funcionariales; el Cuerpo de Ujieres es el séptimo.</li><li>Ingreso: mérito y capacidad. Oposición libre + turno restringido (25 %) + reserva discapacidad (10 %).</li><li>5 situaciones administrativas: activo, servicios especiales, excedencia, expectativa de destino, suspensión.</li></ul>');

-- Esquema de la sección 1
INSERT INTO opouj_wp_uji_esquemas (tema_id, nodo_id, contenido_html)
SELECT 9, id, '<h2>1. Introducción</h2><h3>Fundamento</h3><ul><li>Autonomía parlamentaria (<span class="uji-esq__ref">art. 72.1 CE</span>): normativa, presupuestaria y de personal.</li><li>Administración parlamentaria propia, no integrada en la AGE ni dirigida por el Gobierno.</li></ul><h3>Estatuto vigente</h3><table><tr><th>Dato</th><th>Detalle</th></tr><tr><td>Aprobación</td><td>Mesas Congreso + Senado, 20-11-2025</td></tr><tr><td>Publicación</td><td>BOCG, 21-11-2025</td></tr><tr><td>Entrada en vigor</td><td>Día siguiente (retribuciones: 1-1-2026)</td></tr><tr><td>Deroga</td><td>Estatuto 2006 y modificaciones 2008 / 2009 / 2016</td></tr><tr><td>Estructura</td><td>8 capítulos (arts. 1-86) + disposiciones</td></tr></table>'
FROM opouj_wp_uji_nodos WHERE tema_id = 9 AND tipo = 'seccion' AND numero = '1';

-- Esquema de la sección 2
INSERT INTO opouj_wp_uji_esquemas (tema_id, nodo_id, contenido_html)
SELECT 9, id, '<h2>2. Tipos de personal de Cortes Generales</h2><table><tr><th>Tipo</th><th>Nombramiento</th><th>Retribución</th><th>Características</th></tr><tr><td>Funcionarios</td><td><ul><li>Nombramiento legal.</li><li>Incorporados con carácter permanente.</li><li>Relación estatutaria de servicios profesionales.</li></ul></td><td><ul><li>Retribuidos con cargo al presupuesto de Cortes Generales.</li></ul></td><td><ul><li>Prestan servicio en el Congreso, en el Senado o Junta Electoral Central.</li></ul></td></tr><tr><td>Eventual</td><td><ul><li>Nombrado y separado libremente por el Presidente de cada Cámara.</li><li>A propuesta del órgano al que se encuentre adscrito.</li><li>Cesará de modo automático cuando cese el titular del órgano al que sirve.</li></ul></td><td><ul><li>El presupuesto de cada Cámara determinará sus retribuciones.</li></ul></td><td><ul><li>Asistencia directa a miembros de la Mesa y a otros parlamentarios.</li><li>Los GP podrán contar con un número determinado por la Mesa de cada Cámara.</li><li>De aplicación el régimen prescrito para los funcionarios en el EPCG.</li><li>En ningún caso podrá ocupar puesto de trabajo ni funciones de los funcionarios.</li></ul></td></tr><tr><td>Cuerpos de la AGE</td><td><ul><li>Dependerá del Presidente y el Secretario General de la Cámara donde esté.</li></ul></td><td></td><td><ul><li>Las Cámaras podrán solicitar del Gobierno la adscripción de otro personal.</li><li>Para las funciones de seguridad.</li><li>Para aquellas funciones no atribuidas a los Cuerpos de Funcionarios de CG.</li></ul></td></tr><tr><td>Laboral</td><td><ul><li>El personal contratado laboralmente lo será por cada Cámara.</li><li>Para funciones no atribuidas en el EPCG a los Cuerpos de funcionarios de CG.</li></ul></td><td><ul><li>Estará retribuido de acuerdo con los créditos de los presupuestos de cada Cámara.</li></ul></td><td><ul><li>Congreso y Senado podrán contratar el personal laboral necesario.</li><li>En puestos de trabajo que prevean las respectivas plantillas orgánicas.</li></ul></td></tr></table>'
FROM opouj_wp_uji_nodos WHERE tema_id = 9 AND tipo = 'seccion' AND numero = '2';

-- Esquema de la sección 3
INSERT INTO opouj_wp_uji_esquemas (tema_id, nodo_id, contenido_html)
SELECT 9, id, '<h2>3. Funcionarios de las Cortes Generales</h2><table><tr><th>Cuerpo</th><th>Titulación exigida</th><th>Funciones</th></tr><tr><td>Letrados</td><td>Licenciado en Derecho</td><td><ul><li>Asesoramiento jurídico y técnico a Presidencia y Mesa, a Comisiones y sus órganos, a Subcomisiones y a Ponencias.</li><li>Redacción, conforme a los acuerdos de dichos órganos, de resoluciones, informes y dictámenes, y levantamiento de las actas.</li><li>Representación y defensa de las Cortes Generales ante los órganos jurisdiccionales y ante el TC. Dirección de la Administración Parlamentaria.</li></ul></td></tr><tr><td>Archiveros/Bibliotecarios</td><td>Licenciado en Filosofía y Letras</td><td><ul><li>Organización y gestión de los recursos documentales y bibliográficos existentes en cada Cámara y su difusión a través de los órganos competentes.</li><li>Cuidado y conservación del patrimonio documental y bibliográfico de las Cortes Generales.</li></ul></td></tr><tr><td>Asesores Facultativos</td><td>Licenciado en especialidad</td><td><ul><li>Asistencia y asesoramiento, informe, estudio y propuesta de nivel superior en las materias propias de su especialidad.</li></ul></td></tr><tr><td>Redactores-Taquígrafos-Estenotipistas</td><td>Diplomado universitario</td><td><ul><li>Reproducción íntegra de las intervenciones y sucesos que tengan lugar en las sesiones del Pleno y de las Comisiones de las Cámaras a las que asistan.</li><li>Redacción del Diario de Sesiones.</li></ul></td></tr><tr><td>Técnico-Administrativo</td><td>Diplomado universitario</td><td><ul><li>Gestión administrativa y parlamentaria, ejecución, inspección e impulso de los procedimientos, y estudio y propuesta de carácter administrativo.</li></ul></td></tr><tr><td>Administrativo</td><td>Bachiller *</td><td><ul><li>Tareas administrativas de trámite y apoyo a las funciones de gestión, estudio y propuesta de carácter administrativo.</li><li>Tratamiento de textos y otras aplicaciones informáticas relativas a la tramitación administrativa. Registro, clasificación, transcripción y archivo de documentos.</li><li>Atención de secretarías.</li></ul></td></tr><tr><td>Ujieres</td><td>Graduado escolar *</td><td><ul><li>Vigilancia, control de accesos y custodia en el interior de los edificios parlamentarios, y control de tránsito interno, orientación y acompañamiento de personas.</li><li>Asistencia y auxilio durante la celebración de reuniones.</li><li>Colaboración en actividades protocolarias.</li><li>Trabajos de reproducción, traslado y distribución de documentos, objetos y otras análogas.</li></ul></td></tr></table><p><em>* Titulaciones históricas de la hoja de resumen; el Estatuto 2025 exige Bachiller/equivalente y Graduado en ESO/equivalente respectivamente.</em></p>'
FROM opouj_wp_uji_nodos WHERE tema_id = 9 AND tipo = 'seccion' AND numero = '3';

-- Esquema de la sección 4
INSERT INTO opouj_wp_uji_esquemas (tema_id, nodo_id, contenido_html)
SELECT 9, id, '<h2>4. Ingreso y cese de funcionarios</h2><h3>Acceso a la condición de funcionario de CG</h3><ul><li>De acuerdo con los principios de mérito y capacidad.</li><li>Discapacidad: principios de igualdad de oportunidades y compensación de desventajas.</li></ul><p>Para ser admitido:</p><ul><li>Nacionalidad española y mayor de edad.</li><li>En posesión de la titulación exigida, o en condiciones de obtenerla.</li><li>No hallarse inhabilitado para el ejercicio de funciones públicas por sentencia firme.</li><li>No padecer enfermedad o discapacidad que impida el desempeño de funciones.</li><li>Cumplir los requisitos que se establezcan en cada convocatoria.</li></ul><ul><li>No podrán establecerse requisitos que supongan discriminación.</li><li>Las CG facilitarán los medios materiales para la formación de aspirantes.</li></ul><h3>Ingreso en los Cuerpos de funcionarios</h3><p>Todos con ocasión de vacante, mediante convocatoria pública, libre y oposición.</p><ul><li>Letrados: Licenciado en Derecho.</li><li>Archiveros/Bibliotecarios: Licenciado en Filosofía y Letras.</li><li>Asesores Facultativos: Licenciado en ciertas especialidades.</li><li>Redactores, Taquígrafos y Estenotipistas: Diplomado universitario.</li><li>Técnico-Administrativo: Diplomado universitario.</li><li>Administrativo: Bachiller.</li><li>Ujieres: Graduado en ESO.</li></ul><p>Corresponde a ambas Cámaras, en reunión conjunta, aprobar la oferta de empleo público.</p><h3>Turno restringido y reserva de plazas</h3><ul><li>Turno restringido: 25 % de las plazas para funcionarios de CG. Si no es entero, con fracción ≥ 0,5 se redondea al alza, salvo convocatorias de menos de 3 plazas.</li><li>Reserva: 10 % para discapacidad superior al 33 %. Mismo criterio de redondeo con 0,5.</li></ul><h3>Promoción interna</h3><ul><li>Para funcionarios de la escala inmediatamente inferior, con 4 años de servicio activo.</li><li>Número de plazas fijado por las Mesas en reunión conjunta.</li><li>Selección por oposición o por concurso-oposición, excluidas las materias de origen.</li><li>Tendrán preferencia para los puestos de trabajo vacantes ofertados.</li></ul><h3>Formación y perfeccionamiento</h3><ul><li>Las CG organizarán y patrocinarán la asistencia a cursos de formación y perfeccionamiento.</li><li>Existirá una unidad de formación en las Secretarías Generales.</li><li>Los órganos de representación de personal podrán conceder permisos para estudios.</li></ul><h3>Adquisición de la condición de funcionario</h3><ul><li>Superación de las pruebas selectivas.</li><li>Nombramiento por los Presidentes.</li><li>Juramento o promesa.</li><li>Toma de posesión (plazo: 1 mes).</li></ul><h3>Pérdida de la condición de funcionario</h3><ul><li>Renuncia.</li><li>Pérdida de nacionalidad.</li><li>Sanción disciplinaria de separación.</li><li>Pena de inhabilitación.</li><li>Jubilación.</li></ul><h3>Jubilación</h3><ul><li>Forzosa.</li><li>Por incapacidad permanente.</li><li>Voluntaria.</li></ul>'
FROM opouj_wp_uji_nodos WHERE tema_id = 9 AND tipo = 'seccion' AND numero = '4';

-- Esquema de la sección 5
INSERT INTO opouj_wp_uji_esquemas (tema_id, nodo_id, contenido_html)
SELECT 9, id, '<h2>5. Situaciones administrativas de los funcionarios de CG</h2><table><tr><th>Situación</th><th>Cuándo</th><th>Derechos</th></tr><tr><td>Servicio activo</td><td><ul><li>Ocupen un puesto de trabajo de los adscritos a funcionarios que figuren en las plantillas orgánicas.</li><li>Les haya sido conferida una comisión de servicios de menos de 6 meses.</li></ul></td><td><ul><li>Plenitud de los derechos, deberes y responsabilidades inherentes a su condición.</li></ul></td></tr><tr><td>Servicios especiales</td><td><ul><li>Sean autorizados para realizar una misión por período determinado superior a seis meses.</li><li>Adquieran la condición de funcionarios al servicio de organismos internacionales o de carácter supranacional, o desarrollen su labor al servicio del Estado en el exterior.</li><li>Accedan a cargos políticos o de confianza.</li><li>Accedan a la condición de Diputado, Senador, miembro del Parlamento Europeo, del Parlamento o Asamblea de una CCAA, o cargo local remunerado.</li><li>Accedan a la condición de Magistrado del TC, miembro del CGPJ, Presidente del Consejo de Estado, Consejero de Cuentas o Defensor del Pueblo.</li></ul></td><td><ul><li>Reserva de una plaza del puesto básico del Cuerpo al que perteneciesen.</li><li>Si ocupaban puesto por concurso y pasa menos de un año desde su pase a especiales: derecho a la misma plaza si no está ocupada; si lo está, 75 % del complemento hasta obtener otra plaza igual, en un plazo de dos años.</li><li>Se computa el tiempo a efectos de ascensos, antigüedad y derechos pasivos. Pueden participar en concursos de provisión de puestos.</li><li>Dejarán de percibir las retribuciones que les correspondan como funcionarios de las Cortes Generales, salvo las de antigüedad.</li></ul></td></tr><tr><td>Excedencia voluntaria — por prestación de servicios</td><td><ul><li>Pasen a situación de servicio activo en otros Cuerpos al servicio de las CG o de cualquier organismo público.</li><li>No soliciten reingreso en 30 días tras Servicios Especiales.</li></ul></td><td><ul><li>No devengan derechos económicos, ni es computable el tiempo permanecido en tal situación a efectos de ascenso, antigüedad y derechos pasivos.</li></ul></td></tr><tr><td>Excedencia por interés particular</td><td><ul><li>3 años de servicio activo.</li><li>Subordinada a la buena marcha del servicio.</li><li>No expedientados, ni con sanción pendiente de cumplir.</li></ul></td><td></td></tr><tr><td>Excedencia para el cuidado de hijos</td><td><ul><li>No superior a tres años.</li><li>Para cada hijo.</li></ul></td><td><ul><li>Computable a efectos de ascensos, antigüedad y derechos pasivos.</li><li>Reserva de plaza (1 año); después, puesto equivalente o 75 % del complemento.</li></ul></td></tr><tr><td>Excedencia para el cuidado de familiares</td><td><ul><li>No superior a tres años.</li><li>Familiar hasta segundo grado de consanguinidad o afinidad.</li><li>Que por edad, accidente o enfermedad no pueda valerse por sí mismo.</li></ul></td><td></td></tr><tr><td>Expectativa de destino</td><td><ul><li>Sea imposible obtener el reingreso al servicio activo tras excedencia o suspensión firme.</li></ul></td><td><ul><li>Percibir las retribuciones en concepto de sueldo y antigüedad, cómputo del tiempo a efectos pasivos y de antigüedad. A disposición de las CG.</li></ul></td></tr><tr><td>Suspensión de funciones</td><td><ul><li>Privación temporal del ejercicio de sus funciones y de los derechos inherentes a su condición.</li><li>Puede ser provisional o firme.</li><li>Firme: en virtud de condena criminal o sanción disciplinaria.</li></ul></td><td><ul><li>Provisional: no mayor de 6 meses; derecho al 75 % del salario y antigüedad. Si hay paralización imputable o no comparece, pérdida de toda retribución. Si es absuelto, computa como servicio activo.</li><li>Firme: no superior a 6 años.</li></ul></td></tr><tr><td>Reintegro al servicio activo</td><td><ul><li>No tengan reservada una plaza.</li><li>Haya vacante.</li></ul></td><td><ul><li>Orden de preferencia: suspensos; excedencia por hijos/familiares; excedencia voluntaria por prestación de servicios; excedencia por interés particular.</li></ul></td></tr></table>'
FROM opouj_wp_uji_nodos WHERE tema_id = 9 AND tipo = 'seccion' AND numero = '5';

